"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command 'dos2unix decider.py facilitator.py
git diff --check
git diff --stat
$files = @('"'decider.py','facilitator.py')
foreach ("'$file in $files) {
  $bytes = [System.IO.File]::ReadAllBytes((Join-Path (Get-Location) $file))
  $crlf = 0
  for ($i = 0; $i -lt $bytes.Length - 1; $i++) { if ($bytes[$i] -eq 13 -and $bytes[$i + 1] -eq 10) { $crlf++ } }
  Write-Output "$file CRLF=$crlf"
}'

